 const prompt=`Transparent restaurant game UI sprite for Catchline, hand-painted premium cartoon style matching the supplied Service markers reference. Thick clean midnight navy contours, cream and teal palette, warm gold accents, dimensional soft bevels, warm upper-left highlights; simple strong silhouette readable at 24px. ${subject} No lettering (except explicitly requested punctuation), no watermarks, no background, no ground shadow, no cropped object, no tiny scattered specks. This is one game asset, not a mockup sheet.`;
 store("marker-prompt-"+id,prompt);
 try { const r=await tools.image_gen__imagegen({prompt,referenced_image_paths:[root+"Art/Source/Restaurant/concepts/ui-10-service-markers.png"],transparent_background:true});store("marker-result-"+id,r);text({id,done:true,resultKeys:typeof r==="object"?Object.keys(r):"string"});}
 catch(e){store("marker-error-"+id,String(e));text({id,error:String(e)});}
